document.addEventListener("DOMContentLoaded", function() {
  // Read chatbotId from the config object set by the embed script
  const chatbotId = window.nextwebConfig.chatbotId;

  if (!chatbotId) {
    console.error("Chatbot ID not found. Please check your embed script.");
    return;
  }

  // State
  let isChatOpen = false;

  // SVG Icons
  const chatIcon = `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m3 21 1.65-3.8a9 9 0 1 1 3.4 2.9l-5.05.9 5.05-.9a9 9 0 0 0 11.9-11.9 9 9 0 0 0-11.9-11.9z"></path></svg>`;
  const closeIcon = `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>`;

  // Create a chat icon button
  const chatButton = document.createElement('button');
  chatButton.id = 'nexweb-chat-button';
  chatButton.style.position = 'fixed';
  chatButton.style.bottom = '20px';
  chatButton.style.right = '20px';
  chatButton.style.width = '60px';
  chatButton.style.height = '60px';
  chatButton.style.borderRadius = '50%';
  chatButton.style.backgroundColor = '#007bff';
  chatButton.style.color = 'white';
  chatButton.style.border = 'none';
  chatButton.style.boxShadow = '0 4px 12px rgba(0,0,0,0.15)';
  chatButton.style.cursor = 'pointer';
  chatButton.style.zIndex = '9998';
  chatButton.style.display = 'flex';
  chatButton.style.justifyContent = 'center';
  chatButton.style.alignItems = 'center';
  chatButton.innerHTML = chatIcon;
  document.body.appendChild(chatButton);

  // Create a container for the chat widget iframe
  const chatContainer = document.createElement('div');
  chatContainer.id = 'nexweb-chat-container';
  chatContainer.style.position = 'fixed';
  chatContainer.style.bottom = '20px';
  chatContainer.style.right = '20px';
  chatContainer.style.width = 'min(400px, calc(100vw - 40px))';
  chatContainer.style.height = 'min(600px, calc(100vh - 40px))';
  chatContainer.style.border = 'none';
  chatContainer.style.borderRadius = '10px';
  chatContainer.style.boxShadow = '0 4px 12px rgba(0,0,0,0.15)';
  chatContainer.style.overflow = 'hidden';
  chatContainer.style.zIndex = '9999';
  chatContainer.style.display = 'none'; // Initially hidden
  chatContainer.style.transition = 'opacity 0.3s ease, transform 0.3s ease';
  chatContainer.style.opacity = '0';
  chatContainer.style.transform = 'translateY(20px)';

  // Create the iframe that will host the chat application
  const iframe = document.createElement('iframe');
  iframe.id = 'nexweb-chat-iframe';
  iframe.src = `http://localhost:3000/chat-widget/${chatbotId}`;
  iframe.style.width = '100%';
  iframe.style.height = '100%';
  iframe.style.border = 'none';

  // Append the iframe to the container, and the container to the body
  chatContainer.appendChild(iframe);
  document.body.appendChild(chatContainer);

  // Toggle chat window visibility
  function toggleChat() {
    isChatOpen = !isChatOpen;
    if (isChatOpen) {
      chatContainer.style.display = 'block';
      setTimeout(() => {
        chatContainer.style.opacity = '1';
        chatContainer.style.transform = 'translateY(0)';
      }, 10); // Small delay to allow transition to apply
      chatButton.style.display = 'none';
    } else {
      chatContainer.style.opacity = '0';
      chatContainer.style.transform = 'translateY(20px)';
      setTimeout(() => { chatContainer.style.display = 'none'; }, 300); // Hide after transition
      chatButton.style.display = 'flex';
    }
  }

  // Add click listener to the button
  chatButton.addEventListener('click', toggleChat);

  // Listen for messages from the iframe
  window.addEventListener('message', function(event) {
    // For security, you might want to check event.origin
    // if (event.origin !== 'http://localhost:3000') return;
    
    if (event.data === 'nexweb-chat-close' && isChatOpen) {
      toggleChat();
    }
  });
});
